<?php
/** Temporary tables only. No Research fixtures, posts, live source or worker network. */
function cdca_test_document($brief){$s=$brief['evidence']['sources'][0];return ['title'=>'[TEST MOCK] Database acceptance','summary'=>'TEST MOCK fixture, not an article.','confirmed_facts'=>[['text'=>'TEST MOCK placeholder requiring human review.','source_ids'=>[$s['id']]]],'technical_analysis'=>'TEST MOCK technical structure only; no factual verification performed.','recommendations'=>['TEST MOCK: human review required.'],'sources'=>[['id'=>$s['id'],'url'=>$s['url']]],'uncertainties'=>['Synthetic test fixture, not verified evidence.'],'quotations'=>[],'is_mock'=>true];}
function cdca_database_tests(){
 cdca_need(cdca_stage()&&defined('WP_CLI')&&WP_CLI,'staging_cli_only');global $wpdb;$now=100000;$s=new CDCA_Store($wpdb,$wpdb->prefix.'cdca_test_'.bin2hex(random_bytes(4)).'_',static function()use(&$now){return $now;});$names=['jobs','versions','events','agents'];$checks=0;$check=static function($ok,$name)use(&$checks){cdca_need($ok,'test_'.$name);++$checks;WP_CLI::line('PASS: '.$name);};$throws=static function($f,$code)use($check){try{$f();$check(false,$code);}catch(CDCA_Error $e){$check($e->getMessage()===$code,$code);}};$posts=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->posts}");$research=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}cdra_items");$uid=get_current_user_id();
 try{
  foreach(CDCA_Store::schemas($s->p,$wpdb->get_charset_collate()) as $schema){$s->query(str_replace('CREATE TABLE ','CREATE TEMPORARY TABLE ',$schema));}
  $fixture=cdca_fixture();$id=$s->create($fixture,'news',true,'fixture');$check($s->create($fixture,'news',true,'fixture')===$id,'selection_idempotency');$check($s->read($id)['status']==='selected','selected_state');$s->transition($id,'queued',1,'fixture');$j=$s->claim('worker-one');$check($j['id']===$id&&$s->claim('worker-two')===null,'one_lease_per_job');$throws(static fn()=>$s->heartbeat($id,'worker-two',$j['lease']),'lease_rejected');$s->heartbeat($id,'worker-one',$j['lease']);$doc=cdca_test_document($j['brief']);$bad=$doc;$bad['technical_analysis']='Invented CVE-2099-999999';$throws(static fn()=>$s->complete($id,'worker-one',$j['lease'],hash('sha256','bad'),$bad),'unsupported_cve');$check($s->read($id)['status']==='processing','invalid_output_keeps_job_and_no_version');
  $sub=hash('sha256','submission-1');$v=$s->complete($id,'worker-one',$j['lease'],$sub,$doc);$again=$s->complete($id,'worker-one',$j['lease'],$sub,$doc);$check($v['version']===1&&$again['idempotent']&&(int)$wpdb->get_var("SELECT COUNT(*) FROM {$s->p}versions")===1,'submission_idempotency');$changed=$doc;$changed['summary']='Different';$throws(static fn()=>$s->complete($id,'worker-one',$j['lease'],$sub,$changed),'submission_conflict');
  $throws(static fn()=>$s->transition($id,'in_review',1,'fixture'),'stale_review');$r=$s->read($id);$s->transition($id,'in_review',(int)$r['revision'],'fixture');$r=$s->read($id);$s->transition($id,'approved',(int)$r['revision'],'fixture');$check($s->read($id)['status']==='approved','human_review_approval_is_not_publication');$r=$s->read($id);$throws(static fn()=>$s->transition($id,'published',(int)$r['revision'],'fixture'),'invalid_transition');
  $s->transition($id,'in_review',(int)$r['revision'],'fixture');$r=$s->read($id);$s->transition($id,'queued',(int)$r['revision'],'fixture');$j2=$s->claim('worker-one');$s->complete($id,'worker-one',$j2['lease'],hash('sha256','submission-2'),$doc);$check((int)$wpdb->get_var("SELECT COUNT(*) FROM {$s->p}versions")===2,'immutable_draft_versions');
  $r=$s->read($id);$s->transition($id,'rejected',(int)$r['revision'],'fixture');$r=$s->read($id);$s->transition($id,'selected',(int)$r['revision'],'fixture');$check($s->read($id)['status']==='selected','rejected_to_selected_history');
  $fixture['topic_id']=hash('sha256','offline');$id2=$s->create($fixture,'ai',true,'fixture');$s->transition($id2,'queued',1,'fixture');$lease=$s->claim('offline-worker');$now+=181;$s->recover();$r=$s->read($id2);$check($r['status']==='queued'&&$r['last_error']==='worker_lease_expired'&&(int)$r['attempts']===1,'offline_worker_lease_recovery');$throws(static fn()=>$s->complete($id2,'offline-worker',$lease['lease'],hash('sha256','stale'),$doc),'lease_rejected');$check($s->claim('offline-worker')===null,'retry_backoff');$now+=121;$lease=$s->claim('offline-worker');$s->fail($id2,'offline-worker',$lease['lease'],'adapter_timeout');$now+=241;$lease=$s->claim('offline-worker');$s->fail($id2,'offline-worker',$lease['lease'],'adapter_error');$now+=10000;$check($s->claim('offline-worker')===null&&(int)$s->read($id2)['attempts']===3,'bounded_retry_exhaustion');
  $prior=$s->read($id2)['status'];try{$s->tx(function()use($s,$id2){$s->write($id2,['status'=>'rejected']);$s->query('THIS IS INVALID SQL');});}catch(CDCA_Error $e){}$check($s->read($id2)['status']===$prior,'database_error_rolls_back');
  for($n=0;$n<20;$n++){$s->rate('test-agent');}$throws(static fn()=>$s->rate('test-agent'),'worker_rate_limit');$now+=61;$s->rate('test-agent');$check(true,'rate_window_recovers');
  wp_set_current_user(0);$throws(static fn()=>cdca_admin_authorize('invalid'),'content_forbidden');$u=get_user_by('login','cyberdat_staging_admin');cdca_need($u,'fixture_owner');wp_set_current_user($u->ID);$throws(static fn()=>cdca_admin_authorize('invalid'),'content_nonce');cdca_admin_authorize(wp_create_nonce('cdca_content'));$check(true,'admin_capability_nonce');$check(cdca_worker_permission(new WP_REST_Request('POST','/cyberdat-content/v1/worker')) instanceof WP_Error,'anonymous_worker_rejected');
  $check($posts===(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->posts}")&&$research===(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}cdra_items"),'no_posts_or_research_mutation');WP_CLI::success('Content temporary-table checks: '.$checks.'; all drafts explicitly TEST MOCK.');
 }finally{wp_set_current_user($uid);foreach($names as $name){$wpdb->query("DROP TEMPORARY TABLE IF EXISTS {$s->p}{$name}");}}
}
